mapper.select:
SELECT pc.*, pp.plan_code, u.username as confirmed_by_name,
CASE pc.resource_type WHEN 'PILOT' THEN p.pilot_name WHEN 'DRIVER' THEN d.name WHEN 'PILOT_BOAT' THEN pb.boat_name WHEN 'TUGBOAT' THEN t.tugboat_name ELSE '整体计划' END as resource_name
FROM plan_confirmations pc LEFT JOIN pilotage_plans pp ON pc.plan_id = pp.id LEFT JOIN users u ON pc.confirmed_by = u.id LEFT JOIN pilots p ON pc.resource_type = 'PILOT' AND pc.resource_id = p.id LEFT JOIN drivers d ON pc.resource_type = 'DRIVER' AND pc.resource_id = d.id LEFT JOIN pilot_boats pb ON pc.resource_type = 'PILOT_BOAT' AND pc.resource_id = pb.id LEFT JOIN tugboats t ON pc.resource_type = 'TUGBOAT' AND pc.resource_id = t.id WHERE 1=1
AND pc.plan_id = #{query.planId}
AND pp.plan_code LIKE CONCAT('%', #{query.planCode}, '%')
AND pc.resource_type = #{query.resourceType}
AND pc.confirm_method = #{query.confirmMethod}
AND pc.confirmation_status = #{query.confirmationStatus}
AND pc.confirmed_by = #{query.confirmedBy}
AND DATE(pc.confirmed_at) >= #{query.startDate}
AND DATE(pc.confirmed_at) <= #{query.endDate}
ORDER BY pc.confirmed_at DESC LIMIT #{query.offset}, #{query.pageSize}

SELECT COUNT(*)
FROM plan_confirmations pc
LEFT JOIN pilotage_plans pp ON pc.plan_id = pp.id
WHERE 1=1

    AND pc.plan_id = #{query.planId}


    AND pp.plan_code LIKE CONCAT('%', #{query.planCode}, '%')


    AND pc.resource_type = #{query.resourceType}


    AND pc.confirm_method = #{query.confirmMethod}


    AND pc.confirmation_status = #{query.confirmationStatus}


    AND pc.confirmed_by = #{query.confirmedBy}


    AND DATE(pc.confirmed_at) >= #{query.startDate}


    AND DATE(pc.confirmed_at) <= #{query.endDate}

SELECT COUNT(*) > 0
FROM plan_confirmations
WHERE plan_id = #{planId}
  AND resource_type = #{resourceType}
  AND resource_id = #{resourceId}
  AND confirmation_status = 'CONFIRMED'

SELECT COUNT(*) FROM plan_pilot_assignments pa INNER JOIN pilots p ON pa.pilot_id = p.id INNER JOIN pilotage_plans pp ON pa.plan_id = pp.id LEFT JOIN plan_confirmations pc ON pc.plan_id = pa.plan_id AND pc.resource_type = 'PILOT' AND pc.resource_id = pa.pilot_id WHERE pa.pilot_id = #{pilotId} AND pp.plan_status IN ('PUBLISHED','CONFIRMED','ONGOING','COMPLETED','CERTIFICATED','BILLED','PAID')
AND (pc.id IS NULL OR pc.confirmation_status != 'CONFIRMED') AND pa.status != 'CANCELLED'
AND pa.status = #{status}

SELECT COUNT(*) FROM plan_driver_assignments da INNER JOIN drivers d ON da.driver_id = d.id INNER JOIN pilotage_plans pp ON da.plan_id = pp.id LEFT JOIN plan_confirmations pc ON pc.plan_id = da.plan_id AND pc.resource_type = 'DRIVER' AND pc.resource_id = da.driver_id WHERE da.driver_id = #{driverId} AND pp.plan_status IN ('PUBLISHED','CONFIRMED','ONGOING','COMPLETED','CERTIFICATED','BILLED','PAID')
AND (pc.id IS NULL OR pc.confirmation_status != 'CONFIRMED') AND da.status != 'CANCELLED'
AND da.status = #{status}
